const body = $('Webhook: force-run').first().json.body || {};
const activityId = parseInt(body.activity_id, 10);
const reminderStep = (body.reminder_step || '').toString().trim();
if (!Number.isInteger(activityId)) throw new Error('"activity_id" is required.');
if (!['booking_reminder_24h', 'booking_reminder_2h'].includes(reminderStep)) {
  throw new Error('"reminder_step" must be "booking_reminder_24h" or "booking_reminder_2h".');
}
return [{ json: { activityId, reminderStep } }];

const row = $input.item.json;
if (!row.activity_id) throw new Error('Appointment not found.');
if (!row.email) throw new Error('This contact has no email address on file.');
return [{ json: { ...row, reminder_step: $('Validate Force Payload').item.json.reminderStep } }];

function toTitleCase(s) { return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' '); }
function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
const tmpl = $input.item.json;
const row = $('Prepare Reminder Row').item.json;
const tz = row.timezone || 'America/New_York';
const appointmentTime = row.due_at
  ? DateTime.fromISO(row.due_at, { zone: 'utc' }).setZone(tz).toFormat("EEEE, MMMM d 'at' h:mm a")
  : '';
const unsubUrl = safeEnv('FRONTEND_BASE_URL') + '/unsubscribe/' + (row.unsubscribe_token || '');
const cancelUrl = safeEnv('FRONTEND_BASE_URL') + '/cancel-booking/' + row.activity_id + '?token=' + (row.unsubscribe_token || '');
function fill(t) {
  return (t || '')
    .replace(/{{\s*contact\.first_name\s*}}/gi, toTitleCase(row.first_name) || 'there')
    .replace(/{{\s*contact\.last_name\s*}}/gi, toTitleCase(row.last_name))
    .replace(/{{\s*contact\.email\s*}}/gi, row.email || '')
    .replace(/{{\s*appointment\.start_time\s*}}/gi, appointmentTime)
    .replace(/{{\s*unsubscribe_link\s*}}/gi, unsubUrl)
    .replace(/{{\s*cancel_link\s*}}/gi, cancelUrl)
    .replace(/{{(?!\s*company[._]name\s*}})[^{}]*}}/gi, '');
}
const footer = '<br><br><span style="font-size:11px;color:#94a3b8">Don\'t want these emails? <a href="' + unsubUrl + '">Unsubscribe</a></span>';
return [{ json: { to: row.email, subject: fill(tmpl.subject), htmlBody: fill(tmpl.body).replace(/\n/g, '<br>') + footer } }];
